contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(!c.blacklist(caller));
        vm.deal(caller, 1 ether);

        uint256 totalRemainingBefore = c.totalRemaining();

        vm.prank(caller);
        (bool success, bytes memory data) = address(c).call{value: 0}("XBornID()");

        // If the call succeeded and totalRemaining was >= value, then caller should be blacklisted
        if (success && totalRemainingBefore >= c.value()) {
            assertTrue(c.blacklist(caller), "Caller should be blacklisted after successful distribution");
        }
    }
}

