pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Ensure caller is whitelisted (not blacklisted)
        vm.assume(c.blacklist(caller) == false);
        uint256 initialTotalRemaining = c.totalRemaining();
        uint256 currentValue = c.value();
        vm.assume(initialTotalRemaining < currentValue);
        vm.assume(initialTotalRemaining > 0);

        vm.prank(caller);
        c.getTokens();

        // In the reference, when value > totalRemaining, value is set to totalRemaining (which is >0),
        // so distr gives totalRemaining tokens and sets blacklist[caller] = true.
        // In the mutant, value is set to 0, so toGive = 0, blacklist is not set.
        assertTrue(c.blacklist(caller) == true);
    }
}

