pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.assume(c.blacklist(caller) == false);

        uint256 initialBalance = c.balanceOf(caller);
        bool initialDistFinished = c.distributionFinished();
        uint256 initialTotalRemaining = c.totalRemaining();
        uint256 initialValue = c.value();

        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("XBornID()"));

        // The rule: if tokens were distributed (success implied by no revert), blacklist should be set when toGive > 0
        // Since we cannot get toGive directly, we check if the caller's balance increased and if the blacklist changed
        uint256 newBalance = c.balanceOf(caller);
        bool callerBlacklisted = c.blacklist(caller);

        // If the call succeeded and distribution had not finished and there was remaining value
        if (success && !initialDistFinished && initialTotalRemaining > 0 && initialValue > 0) {
            uint256 toGive = initialValue < initialTotalRemaining ? initialValue : initialTotalRemaining;
            if (toGive > 0) {
                assertTrue(callerBlacklisted == true, "Caller should be blacklisted after receiving tokens via XBornID()");
            }
        }
        // If distribution already finished or no value, blacklist should remain unchanged
        else {
            assertTrue(callerBlacklisted == false, "Caller blacklist should remain unchanged");
        }
    }
}

