pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address, uint256) public {
        // The bug is in burn(): it does not decrease totalDistributed.
        // C initially: totalSupply = 500000000e18, totalDistributed = 200000000e18, totalRemaining = 300000000e18.
        // After XBornID(), totalDistributed becomes balances[owner] = totalDistributed (same value), no change.
        // The invariant: after XBornID(), the difference totalSupply - totalDistributed should equal totalRemaining (if not burned).
        // But if burn is called, the bug makes totalDistributed not decrease, so the difference grows.
        // We can check after XBornID() and burn: totalSupply - totalDistributed should equal totalRemaining + (amount burned).
        // To make it a general rule, we call XBornID() first, then optionally call burn with a random value.
        // But XBornID() is public and can be called only once? Actually it's a constructor-like function but public.
        // Simpler: after XBornID() and possibly burn, the final totalDistributed should equal the initial totalDistributed (200000000e18) minus any burned amount.
        // Because in reference, burn decreases totalDistributed by _value, while bug does not.
        // So after burn, the difference of totalDistributed from initial indicates the bug.
        // We'll check: after XBornID() and burn(_value), totalDistributed == 200000000e18 - _value (if _value <= balanceOf(owner)).
        // For reference, this holds; for bug, it does not.
        // We bound _value to be <= balanceOf(owner) after XBornID().

        // First call XBornID() to set balances[owner] = totalDistributed.
        c.XBornID();

        // Get owner balance (owner is msg.sender initially? Actually contract deployer is owner, here it's this test contract?)
        // Since we call from test contract, owner=address(this). We'll prank as owner? Actually owner = msg.sender of constructor, which is this contract (since test deploys c). So we can call burn directly.
        uint256 ownerBalance = c.balanceOf(address(this));

        // Bound _value to be <= ownerBalance
        vm.assume(_value <= ownerBalance);

        // Call burn
        c.burn(_value);

        // Get final totalDistributed
        uint256 finalTotalDistributed = c.totalDistributed();

        // Expected totalDistributed in reference: 200000000e18 - _value
        uint256 expected = 200000000e18 - _value;
        assertTrue(finalTotalDistributed == expected, "totalDistributed not decreased by _value in burn");
    }
}

