pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 burnValue) public {
        vm.assume(burnValue <= c.totalDistributed());
        vm.prank(c.owner());
        c.XBornID();
        uint256 totalDistBefore = c.totalDistributed();
        vm.prank(c.owner());
        c.burn(burnValue);
        uint256 totalDistAfter = c.totalDistributed();
        assertTrue(totalDistAfter == totalDistBefore - burnValue);
