// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { 
        c = new C(); 
        // Ensure initial value > totalRemaining so we can test edge condition
        // c.value is 1000e18 and totalRemaining is 300000000e18, so value <= totalRemaining is true initially
    }

    function testFuzz_property(address caller) public {
        // Ensure caller is not whitelisted and is not zero
        vm.assume(caller != address(0));

        // Call XBornID() to trigger potential distribution finish
        c.XBornID();

        // Now caller is whitelisted? No, blacklist is false initially, but after distr it will be set true.
        // We need a fresh caller not already blacklisted. Use prank to simulate different addresses.
        vm.assume(c.blacklist(caller) == false);

        // Ensure value <= totalRemaining to avoid require failure from getTokens
        uint256 remaining = c.totalRemaining();
        uint256 currentValue = c.value();
        vm.assume(currentValue <= remaining);

        // Now call getTokens() - it should succeed for reference but might fail for bug
        // We check that it does not revert (the reference should not revert)
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("getTokens()"));

        // The property: getTokens() should succeed (reference does, bug might revert if distributionFinished is false)
        assertTrue(success, "getTokens() should not revert");
    }
}
